const wl = [
  { symbol:'SPY', cboe:'SPY' }, { symbol:'QQQ', cboe:'QQQ' }, { symbol:'IWM', cboe:'IWM' }, { symbol:'DIA', cboe:'DIA' },
  { symbol:'NVDA', cboe:'NVDA' }, { symbol:'TSLA', cboe:'TSLA' }, { symbol:'AAPL', cboe:'AAPL' }, { symbol:'AMD', cboe:'AMD' },
  { symbol:'META', cboe:'META' }, { symbol:'MSFT', cboe:'MSFT' }, { symbol:'AMZN', cboe:'AMZN' }, { symbol:'GOOGL', cboe:'GOOGL' }
];
return wl.map(function (w) { return { json: w }; });

// source_as_of: the CBOE payload's own top-level `timestamp`. Observed 2026-09-15 01:07 UTC: SPY.json carried
// "2026-09-15 00:51:56" (~15 min earlier in UTC), so it is interpreted as UTC. The raw string is kept in
// source_timestamp_raw so the assumption can be checked. received_at is set by the database.
const resp = $input.all();
const wl = $('Watchlist').all();
const out = [];
const NOW = Date.now();
const MAXEXP = NOW + 75 * 86400000;
for (let i = 0; i < resp.length; i++) {
  const body = resp[i] && resp[i].json;
  const sym = wl[i] && wl[i].json && wl[i].json.symbol;
  if (!sym || !body || !body.data || !Array.isArray(body.data.options)) { continue; }
  const opts = body.data.options;
  let spot = Number(body.data.current_price != null ? body.data.current_price : (body.data.close != null ? body.data.close : 0));
  const byKey = {};
  for (let j = 0; j < opts.length; j++) {
    const o = opts[j];
    const m = String(o.option || '').match(/([0-9]{6})([CP])([0-9]{8})$/);
    if (!m) { continue; }
    const expiry = '20' + m[1].slice(0, 2) + '-' + m[1].slice(2, 4) + '-' + m[1].slice(4, 6);
    const ed = Date.parse(expiry + 'T00:00:00Z');
    if (isNaN(ed) || ed < NOW - 86400000 || ed > MAXEXP) { continue; }
    const strike = parseInt(m[3], 10) / 1000;
    const type = m[2];
    const key = expiry + '|' + strike;
    if (!byKey[key]) { byKey[key] = { e: expiry, k: strike }; }
    const c = byKey[key];
    const oi = Number(o.open_interest || 0), vol = Number(o.volume || 0), gm = Number(o.gamma || 0);
    const bid = Number(o.bid || 0), ask = Number(o.ask || 0);
    const mid = (bid > 0 && ask > 0) ? (bid + ask) / 2 : Number(o.last_trade_price || 0);
    if (type === 'C') { c.coi = oi; c.cg = gm; c.cv = vol; c.cmid = mid; }
    else { c.poi = oi; c.pg = gm; c.pv = vol; c.pmid = mid; }
  }
  let cells = Object.keys(byKey).map(function (k) { return byKey[k]; });
  if (!(spot > 0)) {
    let best = null;
    for (const c of cells) { if (c.cmid > 0 && c.pmid > 0) { const d = Math.abs(c.cmid - c.pmid); if (best === null || d < best.d) { best = { d: d, s: c.k + (c.cmid - c.pmid) }; } } }
    spot = best ? best.s : 0;
  }
  if (!(spot > 0)) { continue; }
  cells = cells.filter(function (c) { return c.k >= spot * 0.80 && c.k <= spot * 1.20; })
    .map(function (c) { return { e: c.e, k: c.k, coi: c.coi || 0, poi: c.poi || 0, cg: c.cg || 0, pg: c.pg || 0, cv: c.cv || 0, pv: c.pv || 0 }; });
  if (!cells.length) { continue; }
  out.push({ json: { symbol: sym, as_of: new Date().toISOString(), source_as_of: (body.timestamp ? String(body.timestamp).replace(' ', 'T') + 'Z' : null), source_timestamp_raw: (body.timestamp || null),  spot: Math.round(spot * 100) / 100, cells: cells, cell_count: cells.length } });
}
return out;
